// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

class NativeMembershipProbeReuseTest {
	static final String FLAG = "rdf4j.lmdb.expressionDomain.reuseMembershipMissSlot";

	@Test
	void emptySlotAndCollisionChainAreProbedOnce() {
		try (var fixture = new NativeMembershipBulkIoTest.Fixture(1)) {
			assertTrue(fixture.membership.add(new long[] { 0 }, 0));
			long empty = keyForBucket(1, 63, 1);
			fixture.indexFile.reads = 0;
			assertTrue(fixture.membership.add(new long[] { empty }, empty));
			assertEquals(Boolean.getBoolean(FLAG) ? 1 : 2, fixture.indexFile.reads);
			long collision = keyForBucket(1, 63, 0);
			fixture.indexFile.reads = 0;
			assertTrue(fixture.membership.add(new long[] { collision }, collision));
			assertEquals(Boolean.getBoolean(FLAG) ? 3 : 6, fixture.indexFile.reads);
			fixture.indexFile.reads = 0;
			assertFalse(fixture.membership.add(new long[] { collision }, -1));
			assertEquals(3, fixture.indexFile.reads);
		}
	}

	@Test
	void growthInvalidatesOldEmptySlotAndPreservesEveryKey() {
		try (var fixture = new NativeMembershipBulkIoTest.Fixture(1)) {
			List<Long> keys = new ArrayList<>();
			long candidate = 0;
			for (int i = 0; i < 48; i++) {
				candidate = keyForBucket(candidate, 127, 0);
				keys.add(candidate);
				assertTrue(fixture.membership.add(new long[] { candidate }, candidate));
				candidate++;
			}
			long grows = keyForBucket(1, 127, 112);
			keys.add(grows);
			assertTrue(fixture.membership.add(new long[] { grows }, grows));
			assertEquals(3, fixture.paths.size(), "growth must replace the index");
			for (long key : keys) {
				assertFalse(fixture.membership.add(new long[] { key }, -1));
			}
			List<Long> outcomes = new ArrayList<>();
			fixture.membership.forEachId(outcomes::add);
			assertEquals(keys, outcomes);
			assertEquals(49, fixture.membership.size());
		}
	}

	@Test
	void indexWriteFailureCleansUpWithoutPublishingMembership() {
		try (var fixture = new NativeMembershipBulkIoTest.Fixture(1)) {
			assertTrue(fixture.membership.add(new long[] { 0 }, 0));
			fixture.indexFile.failWrite = true;
			assertThrows(java.io.UncheckedIOException.class,
					() -> fixture.membership.add(new long[] { 1 }, 1));
			assertEquals(0, fixture.ledger.usedBytes());
			assertEquals(1, fixture.membership.size());
		}
	}

	private static long keyForBucket(long start, long mask, long bucket) {
		for (long value = start;; value++) {
			if ((mix(mix(value)) & mask) == bucket) {
				return value;
			}
		}
	}

	private static long mix(long value) {
		value = (value ^ value >>> 30) * 0xbf58476d1ce4e5b9L;
		value = (value ^ value >>> 27) * 0x94d049bb133111ebL;
		return value ^ value >>> 31;
	}
}
